const DAILY_REMINDERS = [
  { arabic: "إِنَّ مَعَ الْعُسْرِ يُسْرًا", source: "سورة الشرح: ٦", note: "بعد كل ضيق فرج قريب" },
  { arabic: "فَإِنَّ مَعَ الْعُسْرِ يُسْرًا", source: "سورة الشرح: ٥", note: "العسر لا يدوم" },
  { arabic: "أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ", source: "سورة الرعد: ٢٨", note: "ذكر الله دواء القلوب" },
  { arabic: "وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ", source: "سورة هود: ٨٨", note: "لا حول ولا قوة إلا بالله" },
  { arabic: "إِنَّ اللَّهَ مَعَ الصَّابِرِينَ", source: "سورة البقرة: ١٥٣", note: "اصبر فالله معك" },
  { arabic: "لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا", source: "سورة التوبة: ٤٠", note: "الله معك فلا تحزن" },
  { arabic: "وَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَّكُمْ", source: "سورة البقرة: ٢١٦", note: "رب خير في ما تكره" },
  { arabic: "وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ", source: "سورة الطلاق: ٣", note: "توكل على الله يكفيك" },
  { arabic: "وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ", source: "سورة الأعراف: ١٥٦", note: "رحمته وسعت كل شيء" },
  { arabic: "لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا", source: "سورة البقرة: ٢٨٦", note: "الله لا يكلفك فوق طاقتك" },
  { arabic: "فَاذْكُرُونِي أَذْكُرْكُمْ", source: "سورة البقرة: ١٥٢", note: "اذكر الله يذكرك" },
  { arabic: "وَلَذِكْرُ اللَّهِ أَكْبَرُ", source: "سورة العنكبوت: ٤٥", note: "الذكر أعظم من كل شيء" },
  { arabic: "إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِّنَ الْمُحْسِنِينَ", source: "سورة الأعراف: ٥٦", note: "رحمته قريبة منك" },
  { arabic: "وَمَا عَلَيْنَا إِلَّا الْبَلَاغُ الْمُبِينُ", source: "سورة يس: ١٧", note: "عليك البلاغ لا النتيجة" },
  { arabic: "قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَٰلِكَ فَلْيَفْرَحُوا", source: "سورة يونس: ٥٨", note: "فضل الله ورحمته سبب للفرح" },
  { arabic: "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا", source: "سورة آل عمران: ٨", note: "اللهم ثبت قلبي على دينك" },
  { arabic: "وَاللَّهُ يُحِبُّ الصَّابِرِينَ", source: "سورة آل عمران: ١٤٦", note: "صبرك محبوب عند الله" },
  { arabic: "سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ", source: "سورة الصافات: ١٨٠", note: "سبحان الله وبحمده" },
  { arabic: "وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ", source: "سورة غافر: ٦٠", note: "ادعُه يستجب لك" },
  { arabic: "فَلَا تَخْشَوُا النَّاسَ وَاخْشَوْنِ", source: "سورة المائدة: ٤٤", note: "لا تخف إلا الله" },
  { arabic: "وَاللَّهُ غَفُورٌ رَّحِيمٌ", source: "سورة البقرة: ١٧٣", note: "الله غفور رحيم .. لا تيأس" },
  { arabic: "فَاصْبِرْ ۖ إِنَّ الْعَاقِبَةَ لِلْمُتَّقِينَ", source: "سورة هود: ٤٩", note: "العاقبة لأهل التقوى" },
  { arabic: "وَلَا تَيْأَسُوا مِن رَّوْحِ اللَّهِ ۖ إِنَّهُ لَا يَيْأَسُ مِن رَّوْحِ اللَّهِ إِلَّا الْقَوْمُ الْكَافِرُونَ", source: "سورة يوسف: ٨٧", note: "لا تيأس من روح الله أبداً" },
  { arabic: "أَنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ", source: "سورة البقرة: ٢٣١", note: "الله يعلم ما في قلبك" },
  { arabic: "إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ", source: "سورة النساء: ٤٠", note: "لا يُضاع أجرك أبداً" },
  { arabic: "وَكَفَىٰ بِاللَّهِ شَهِيدًا", source: "سورة الفتح: ٢٨", note: "حسبنا الله ونعم الوكيل" },
  { arabic: "وَمَا أُوتِيتُم مِّنَ الْعِلْمِ إِلَّا قَلِيلًا", source: "سورة الإسراء: ٨٥", note: "تواضع لله بعلمك" },
  { arabic: "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", source: "سورة البقرة: ٢٠١", note: "أجمع دعاء في آية" },
  { arabic: "وَاللَّهُ خَيْرٌ وَأَبْقَىٰ", source: "سورة طه: ٧٣", note: "ما عند الله خير وأبقى" },
  { arabic: "فَلِلَّهِ الْحَمْدُ رَبِّ السَّمَاوَاتِ وَرَبِّ الْأَرْضِ", source: "سورة الجاثية: ٣٦", note: "الحمد لله على كل حال" },
  { arabic: "وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ", source: "سورة البقرة: ١٥٣", note: "استعن بالصبر والصلاة" },
  { arabic: "إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ", source: "سورة البقرة: ٢٢٢", note: "تب إلى الله يحبك" },
  { arabic: "رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا", source: "سورة البقرة: ٢٨٦", note: "اللهم اغفر لنا تقصيرنا" },
  { arabic: "وَاللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ", source: "سورة النساء: ٢٧", note: "الله يريد توبتك" },
  { arabic: "يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ ۖ وَعِندَهُ أُمُّ الْكِتَابِ", source: "سورة الرعد: ٣٩", note: "كل شيء بقدر الله" },
  { arabic: "إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ", source: "سورة الرعد: ١١", note: "بداية التغيير من نفسك" },
  { arabic: "وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ", source: "سورة البقرة: ١٠٥", note: "فضل الله عظيم فلا تقنط" },
  { arabic: "وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًا", source: "سورة النور: ٢١", note: "برحمته تزكو نفوسنا" },
  { arabic: "فَاسْأَلُوا أَهْلَ الذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ", source: "سورة النحل: ٤٣", note: "تعلَّم واسأل أهل العلم" },
  { arabic: "وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا", source: "سورة الطلاق: ٢", note: "تقوى الله تفتح لك المخارج" },
  { arabic: "وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مِنْ أَمْرِهِ يُسْرًا", source: "سورة الطلاق: ٤", note: "التقوى تجلب اليسر" },
  { arabic: "وَمَن يَتَّقِ اللَّهَ يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُعْظِمْ لَهُ أَجْرًا", source: "سورة الطلاق: ٥", note: "التقوى تكفر الذنوب وتعظم الأجر" },
  { arabic: "وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ ۚ إِنَّ اللَّهَ بَالِغُ أَمْرِهِ", source: "سورة الطلاق: ٣", note: "من توكل على الله كفاه" },
  { arabic: "وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ", source: "سورة الأنفال: ٣٣", note: "بركة وجود المؤمنين" },
  { arabic: "إِنَّ اللَّهَ يُدَافِعُ عَنِ الَّذِينَ آمَنُوا", source: "سورة الحج: ٣٨", note: "الله يدافع عنك" },
  { arabic: "رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا", source: "سورة الإسراء: ٢٤", note: "اللهم ارحم والديّ" },
  { arabic: "فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ", source: "سورة التغابن: ١٦", note: "اتق الله ما استطعت" },
  { arabic: "وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ", source: "سورة النحل: ١٢٧", note: "صبرك بالله لا بنفسك" },
  { arabic: "إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوا وَّالَّذِينَ هُم مُّحْسِنُونَ", source: "سورة النحل: ١٢٨", note: "الله مع المتقين والمحسنين" },
  { arabic: "إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ", source: "سورة البقرة: ١٩٥", note: "كن محسناً يحبك الله" },
  { arabic: "وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا عَمَّا يَعْمَلُ الظَّالِمُونَ", source: "سورة إبراهيم: ٤٢", note: "الله لا يغفل عن ظلم أحد" },
  { arabic: "وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", source: "سورة البقرة: ٢٨٤", note: "الله على كل شيء قدير" },
  { arabic: "وَمَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ", source: "سورة الكهف: ٣٩", note: "لا حول ولا قوة إلا بالله" },
  { arabic: "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", source: "سورة البقرة: ١٥٦", note: "منه جئنا وإليه نعود" },
  { arabic: "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", source: "سورة الفاتحة: ٢", note: "الحمد لله رب كل شيء" },
  { arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", source: "سورة الفاتحة: ١", note: "ابدأ دائماً باسم الله" },
  { arabic: "وَمَا أَدْرَاكَ مَا الْعَقَبَةُ", source: "سورة البلد: ١٢", note: "فك رقبة أو إطعام" },
  { arabic: "إِنَّ الْإِنسَانَ لَفِي خُسْرٍ", source: "سورة العصر: ٢", note: "الوقت هو رأس مالك فلا تضيعه" },
  { arabic: "إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ", source: "سورة العصر: ٣", note: "الإيمان والعمل الصحيح سر النجاح" },
  { arabic: "فَوَيْلٌ لِّلْمُصَلِّينَ", source: "سورة الماعون: ٤", note: "صلِّ بخشوع لا رياء" },
  { arabic: "إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ", source: "سورة الكوثر: ١", note: "الله أعطاك بلا حساب" },
  { arabic: "فَصَلِّ لِرَبِّكَ وَانْحَرْ", source: "سورة الكوثر: ٢", note: "صلِّ لربك وقرِّب له" },
  { arabic: "قُلْ هُوَ اللَّهُ أَحَدٌ", source: "سورة الإخلاص: ١", note: "الله أحد لا شبيه له" },
  { arabic: "اللَّهُ الصَّمَدُ", source: "سورة الإخلاص: ٢", note: "الله هو الملجأ في كل شيء" },
  { arabic: "لَمْ يَلِدْ وَلَمْ يُولَدْ", source: "سورة الإخلاص: ٣", note: "الله الأحد الفرد الصمد" },
  { arabic: "وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ", source: "سورة الإخلاص: ٤", note: "لا أحد يعادل الله" },
  { arabic: "فَلَوْلَا نُوحِدُهُ وَنَسْتَغْفِرُهُ", note: "واجعل لسانك رطباً بذلك" },
];

